"""Copy every settlement from the Clearwell Settlements API into settlements.jsonl."""
import argparse
import json
import time
import urllib.error
import urllib.request

QUERY = """
query Settlements($first: Int, $after: String) {
  settlements(first: $first, after: $after) {
    nodes { id batchDate amountCents currency status }
    pageInfo { endCursor hasNextPage }
  }
}
"""
PAGE_SIZE = 100
MAX_PAGES = 1_000_000
MAX_RESTARTS = 10
MAX_RETRIES = 20


class GraphQLError(RuntimeError):
    pass


def graphql(url, query, variables=None):
    body = json.dumps({"query": query, "variables": variables or {}}).encode()
    for _ in range(MAX_RETRIES + 1):
        req = urllib.request.Request(url, data=body, headers={"Content-Type": "application/json"})
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as exc:
            if exc.code == 429:
                retry_after = exc.headers.get("Retry-After")
                try:
                    delay = float(retry_after) if retry_after is not None else 1.0
                except ValueError:
                    delay = 1.0
                time.sleep(max(delay, 0.0))
                continue
            # A malformed/expired cursor is reported as a GraphQL error, possibly
            # with a 400 status. Return the body so the caller can restart.
            try:
                result = json.load(exc)
            except (ValueError, OSError):
                raise
            if isinstance(result, dict) and result.get("errors"):
                return result
            raise
    raise RuntimeError("too many rate-limited requests")


def fetch_settlements(url, after):
    variables = {"first": PAGE_SIZE, "after": after}
    result = graphql(url, QUERY, variables)
    if result.get("errors"):
        raise GraphQLError(result["errors"])
    return result["data"]["settlements"]


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", required=True)
    ap.add_argument("--out", default="settlements.jsonl")
    args = ap.parse_args()

    url = f"{args.base_url.rstrip('/')}/v2/graphql"
    settlements = {}
    after = None
    restarts = 0
    pages = 0

    while True:
        try:
            connection = fetch_settlements(url, after)
        except GraphQLError:
            if after is not None and restarts < MAX_RESTARTS:
                # Expired or malformed cursor: start the traversal again.
                restarts += 1
                after = None
                continue
            raise

        for settlement in connection["nodes"]:
            # Amended settlements are delivered again; the last version wins.
            settlements[settlement["id"]] = settlement

        page_info = connection["pageInfo"]
        if not page_info["hasNextPage"]:
            break

        pages += 1
        if pages > MAX_PAGES:
            raise RuntimeError("too many pages")
        after = page_info["endCursor"]
        if after is None:
            raise RuntimeError("pageInfo.hasNextPage is true but endCursor is missing")

    with open(args.out, "w") as f:
        for settlement in settlements.values():
            f.write(json.dumps(settlement) + "\n")
    print(f"reconciled {len(settlements)} settlements")


if __name__ == "__main__":
    main()

